{
  "database": {
    "tables": [
      {
        "name": "bundles",
        "purpose": "Master record for each merchant-defined bundle, its type, enabled state, and the Shopify discount node backing it.",
        "columns": [
          { "name": "id",                          "sqlType": "UUID",        "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()",     "purpose": "internal id" },
          { "name": "name",                         "sqlType": "TEXT",        "constraints": "NOT NULL",                                   "purpose": null },
          { "name": "bundle_type",                  "sqlType": "TEXT",        "constraints": "NOT NULL",                                   "purpose": "fixed or flexible", "enum": ["fixed", "flexible"] },
          { "name": "enabled",                      "sqlType": "BOOLEAN",     "constraints": "NOT NULL DEFAULT true",                      "purpose": null },
          { "name": "required_item_count",           "sqlType": "INTEGER",     "constraints": "NULL",                                       "purpose": "for flexible bundles: how many items the customer must pick from the pool" },
          { "name": "discount_type",                "sqlType": "TEXT",        "constraints": "NOT NULL",                                   "purpose": "percentage, flat, or bxgy", "enum": ["percentage", "flat", "bxgy"] },
          { "name": "shopify_discount_external_id", "sqlType": "TEXT",        "constraints": "NULL",                                       "purpose": "Shopify DiscountCodeNode id, stored so the discount can be updated or deleted when the bundle changes" },
          { "name": "discount_code_string",         "sqlType": "TEXT",        "constraints": "NULL",                                       "purpose": "the code string generated by Shopify at bundle creation time; used to apply the discount via cartDiscountCodesUpdate and to match against discount_codes[].code in the orders/create webhook payload for purchase-count attribution" },
          { "name": "purchase_count",               "sqlType": "INTEGER",     "constraints": "NOT NULL DEFAULT 0",                         "purpose": "incremented each time this bundle is added to a cart and confirmed via order creation" },
          { "name": "created_at",                   "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()",                     "purpose": null },
          { "name": "updated_at",                   "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()",                     "purpose": null }
        ],
        "uniqueConstraint": [],
        "indexes": [["enabled", "created_at"]],
        "foreignKeys": []
      },
      {
        "name": "bundle_items",
        "purpose": "Each product/variant slot that belongs to a bundle's fixed set or flexible pool.",
        "columns": [
          { "name": "id",                   "sqlType": "UUID",    "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "bundle_id",            "sqlType": "UUID",    "constraints": "NOT NULL REFERENCES bundles(id) ON DELETE CASCADE", "purpose": "parent bundle" },
          { "name": "product_external_id",  "sqlType": "BIGINT",  "constraints": "NOT NULL",                              "purpose": "Shopify product id for this slot" },
          { "name": "variant_mode",         "sqlType": "TEXT",    "constraints": "NOT NULL",                              "purpose": "all (any variant) or specific (only listed variants)", "enum": ["all", "specific"] },
          { "name": "available",            "sqlType": "BOOLEAN", "constraints": "NOT NULL DEFAULT true",                 "purpose": "set false when products/update shows the product inactive or products/delete fires; widget reads this to show disabled state" }
        ],
        "uniqueConstraint": ["bundle_id", "product_external_id"],
        "indexes": [["bundle_id"], ["product_external_id"]],
        "foreignKeys": []
      },
      {
        "name": "bundle_item_variants",
        "purpose": "Explicit variant constraints for bundle items whose variant_mode is 'specific'.",
        "columns": [
          { "name": "id",                  "sqlType": "UUID",   "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "bundle_item_id",      "sqlType": "UUID",   "constraints": "NOT NULL REFERENCES bundle_items(id) ON DELETE CASCADE", "purpose": "parent bundle item" },
          { "name": "variant_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL",                             "purpose": "Shopify ProductVariant id allowed for this slot" }
        ],
        "uniqueConstraint": ["bundle_item_id", "variant_external_id"],
        "indexes": [["bundle_item_id"]],
        "foreignKeys": []
      },
      {
        "name": "bundle_discount_tiers",
        "purpose": "Tiered discount rules for a bundle; the best-matching tier is selected at checkout based on item count.",
        "columns": [
          { "name": "id",              "sqlType": "UUID",    "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "bundle_id",       "sqlType": "UUID",    "constraints": "NOT NULL REFERENCES bundles(id) ON DELETE CASCADE", "purpose": "parent bundle" },
          { "name": "min_item_count",  "sqlType": "INTEGER", "constraints": "NOT NULL",                              "purpose": "minimum number of items in the bundle to qualify for this tier" },
          { "name": "discount_ratio",  "sqlType": "TEXT",    "constraints": "NULL",                                  "purpose": "populated when discount_type is percentage; mutually exclusive with discount_amount" },
          { "name": "discount_amount", "sqlType": "BIGINT",  "constraints": "NULL",                                  "purpose": "populated when discount_type is flat; mutually exclusive with discount_ratio" },
          { "name": "is_bxgy",         "sqlType": "BOOLEAN", "constraints": "NOT NULL DEFAULT false",                "purpose": "true when this tier represents a buy-X-get-one-free rule; discount_ratio and discount_amount are both null in this case" }
        ],
        "uniqueConstraint": ["bundle_id", "min_item_count"],
        "indexes": [["bundle_id"]],
        "foreignKeys": []
      },
      {
        "name": "bundle_order_increments",
        "purpose": "Deduplication ledger ensuring purchase_count is incremented at most once per order per bundle.",
        "columns": [
          { "name": "id",               "sqlType": "UUID",        "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "bundle_id",        "sqlType": "UUID",        "constraints": "NOT NULL REFERENCES bundles(id) ON DELETE CASCADE", "purpose": "bundle whose count was incremented" },
          { "name": "order_external_id","sqlType": "BIGINT",      "constraints": "NOT NULL",                              "purpose": "Shopify order id that triggered the increment" },
          { "name": "created_at",       "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()",                "purpose": null }
        ],
        "uniqueConstraint": ["bundle_id", "order_external_id"],
        "indexes": [["bundle_id", "order_external_id"]],
        "foreignKeys": []
      }
    ]
  },
  "shopifyIntegration": {
    "webhookTopics": ["orders/create", "products/update", "products/delete"],
    "cronSchedule": null
  },
  "httpRoutes": {
    "widget": [
      { "method": "GET",  "path": "/widget/bundles",          "paginationKind": "cursor" },
      { "method": "POST", "path": "/widget/bundles/add-to-cart" }
    ],
    "admin": [
      { "method": "GET",    "path": "/admin/bundles",          "paginationKind": "cursor" },
      { "method": "POST",   "path": "/admin/bundles/create" },
      { "method": "PUT",    "path": "/admin/bundles/update" },
      { "method": "DELETE", "path": "/admin/bundles/delete" },
      { "method": "GET",    "path": "/admin/products/search",  "paginationKind": "cursor" }
    ]
  }
}
